// build a concrete request path for route r, plus expected params
func zzConcrete(rnd *rand.Rand, r zzR) (string, []Param) {
	var parts []string
	var ps []Param
	for _, s := range r.segs {
		switch {
		case strings.HasPrefix(s, "*"):
			v := fmt.Sprintf("/r%d/e", rnd.Intn(1000))
			ps = append(ps, Param{s[1:], v})
			parts = append(parts, strings.TrimPrefix(v, "/"))
		case strings.Contains(s, ":"):
			idx := strings.Index(s, ":")
			v := fmt.Sprintf("v%d", rnd.Intn(1000))
			ps = append(ps, Param{s[idx+1:], v})
			parts = append(parts, s[:idx]+v)
		default:
			parts = append(parts, s)
		}
	}
	return "/" + strings.Join(parts, "/"), ps
}

